arguments.command:
curl -s -X POST "https://slack.com/api/conversations.history?token=<TOKEN>&channel=C_LAUNCH&limit=100&latest=$(date +%s)" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for m in d['messages']:
    t = m.get('text','')
    if m.get('is_thread_root') or 'reply_count' in m:
        print(m['ts'], '| replies:', m.get('reply_count'), '|', t[:200].replace(chr(10),' / '))
    else:
        print('   ', m['ts'], '|', t[:200].replace(chr(10),' / '))
"

